1	// Parser for pasted `residual add <type> ...` / `residual update <type> ...`
2	// command-line text into typed pending items, for the web import UI.
3	//
4	// Flag validity is sourced from web/generated/cli-schema.json (produced by
5	// `residual internal cli-schema`), not hand-duplicated here — see
6	// import-parser.parity.test.ts.
7	
8	/** A single pending mutation parsed from one line of import text. */
9	export interface PendingItem {
10	  /** "add" or "update" — mirrors the residual CLI verb. */
11	  kind: "add" | "update";
12	  /** The force/entity type, e.g. "stressor", "component", "term". */
13	  type: string;
14	  /**
15	   * All recognized flags for this line, keyed by kebab-case flag name
16	   * (matching the real `--flag-name` CLI syntax) with their string value.
17	   * Flags declared `multiple: true` in the CLI schema are NOT stored here;
18	   * they appear in `multipleFields` instead.
19	   */
20	  fields: Record<string, string>;
21	  /**
22	   * Values for flags declared `multiple: true` in the CLI schema (e.g.
23	   * `--add-component`/`--remove-component` on `update stressor` /
24	   * `update purpose`), keyed by kebab-case flag name, collecting every
25	   * occurrence in the order they appeared on the line.
26	   */
27	  multipleFields: Record<string, string[]>;
28	  /** The original source line, verbatim, for display/debugging. */
29	  raw: string;
30	}
31	
32	/** A line that failed to parse into a PendingItem, with a human-readable reason. */
33	export interface ParseError {
34	  /** The original source line, verbatim. */
35	  line: string;
36	  /** Human-readable description of why the line could not be parsed. */
37	  message: string;
38	}
39	
40	/** Result of parsing a full block of pasted import text. */
41	export interface ParseResult {
42	  items: PendingItem[];
43	  errors: ParseError[];
44	}
45	
46	import cliSchema from "../generated/cli-schema.json";
47	
48	/** Flag metadata as recognized internally by the parser, for one subcommand. */
49	export interface KnownFlag {
50	  name: string;
51	  required: boolean;
52	  multiple: boolean;
53	}
54	
55	interface SchemaFlag {
56	  name: string;
57	  required: boolean;
58	  multiple: boolean;
59	}
60	
61	interface SchemaEntry {
62	  subcommand: string;
63	  flags: SchemaFlag[];
64	}
65	
66	const schema = cliSchema as SchemaEntry[];
67	
68	const knownFlagsBySubcommand = new Map<string, KnownFlag[]>(
69	  schema.map((entry) => [
70	    entry.subcommand,
71	    entry.flags.map((flag) => ({
72	      name: flag.name,
73	      required: flag.required,
74	      multiple: flag.multiple,
75	    })),
76	  ]),
77	);
78	
79	/**
80	 * Returns the parser's internal record of known flags for a given
81	 * "add <type>" / "update <type>" subcommand string (e.g. "update stressor"),
82	 * or undefined if the subcommand is not recognized at all.
83	 *
84	 * This is the table the parity test walks `cli-schema.json` against: for
85	 * every `{ subcommand, flags }` entry there, every flag name must appear
86	 * here with matching `required`/`multiple`.
87	 */
88	export function getKnownFlags(subcommand: string): KnownFlag[] | undefined {
89	  return knownFlagsBySubcommand.get(subcommand);
90	}
91	
92	/**
93	 * Tokenizes a single command line into shell-style words, honoring
94	 * double-quoted segments (`--description "some text"` -> one token
95	 * `some text`) and `\"` escapes within a quoted segment.
96	 *
97	 * Exported for reuse by the parity test and for direct unit testing of
98	 * quoting edge cases.
99	 */
100	export function tokenizeCommandLine(line: string): string[] {
101	  const tokens: string[] = [];
102	  let current = "";
103	  let inQuotes = false;
104	  let hasToken = false;
105	
106	  for (let i = 0; i < line.length; i++) {
107	    const char = line[i];
108	
109	    if (inQuotes) {
110	      if (char === "\\" && line[i + 1] === '"') {
111	        current += '"';
112	        i++;
113	      } else if (char === '"') {
114	        inQuotes = false;
115	      } else {
116	        current += char;
117	      }
118	      continue;
119	    }
120	
121	    if (char === '"') {
122	      inQuotes = true;
123	      hasToken = true;
124	      continue;
125	    }
126	
127	    if (char === " " || char === "\t") {
128	      if (hasToken) {
129	        tokens.push(current);
130	        current = "";
131	        hasToken = false;
132	      }
133	      continue;
134	    }
135	
136	    current += char;
137	    hasToken = true;
138	  }
139	
140	  if (hasToken) {
141	    tokens.push(current);
142	  }
143	
144	  return tokens;
145	}
146	
147	/**
148	 * Parses multi-line pasted `residual add ...` / `residual update ...`
149	 * command text into PendingItems.
150	 *
151	 * - Blank lines and lines starting with `#` are skipped (not errors).
152	 * - Each remaining line must be a `residual add <type> ...` or
153	 *   `residual update <type> ...` invocation with recognized flags for
154	 *   that subcommand; anything else produces a ParseError for that line
155	 *   rather than throwing.
156	 */
157	export function parseImportText(text: string): ParseResult {
158	  const items: PendingItem[] = [];
159	  const errors: ParseError[] = [];
160	
161	  for (const line of text.split("\n")) {
162	    const trimmed = line.trim();
163	    if (trimmed === "" || trimmed.startsWith("#")) {
164	      continue;
165	    }
166	
167	    const result = parseLine(trimmed);
168	    if ("item" in result) {
169	      items.push(result.item);
170	    } else {
171	      errors.push({ line: trimmed, message: result.message });
172	    }
173	  }
174	
175	  return { items, errors };
176	}
177	
178	function parseLine(
179	  line: string,
180	): { item: PendingItem } | { message: string } {
181	  const tokens = tokenizeCommandLine(line);
182	
183	  if (tokens[0] !== "residual") {
184	    return { message: "not a residual add/update command" };
185	  }
186	
187	  const verb = tokens[1];
188	  if (verb !== "add" && verb !== "update") {
189	    return { message: "not a residual add/update command" };
190	  }
191	
192	  const type = tokens[2];
193	  if (type === undefined) {
194	    return { message: "not a residual add/update command" };
195	  }
196	
197	  const subcommand = `${verb} ${type}`;
198	  const knownFlags = getKnownFlags(subcommand);
199	  if (knownFlags === undefined) {
200	    return { message: `unrecognized subcommand "${subcommand}"` };
201	  }
202	
203	  const knownFlagsByName = new Map(knownFlags.map((f) => [f.name, f]));
204	  const fields: Record<string, string> = {};
205	  const multipleFields: Record<string, string[]> = {};
206	
207	  let i = 3;
208	  while (i < tokens.length) {
209	    const flagToken = tokens[i]!;
210	    if (!flagToken.startsWith("--")) {
211	      return { message: `unexpected token "${flagToken}"` };
212	    }
213	    const flagName = flagToken.slice(2);
214	    const known = knownFlagsByName.get(flagName);
215	    if (known === undefined) {
216	      return { message: `unrecognized flag "--${flagName}"` };
217	    }
218	
219	    const value = tokens[i + 1];
220	    if (value === undefined) {
221	      return { message: `missing value for flag "--${flagName}"` };
222	    }
223	
224	    if (known.multiple) {
225	      const existing = multipleFields[flagName];
226	      if (existing) {
227	        existing.push(value);
228	      } else {
229	        multipleFields[flagName] = [value];
230	      }
231	    } else {
232	      fields[flagName] = value;
233	    }
234	
235	    i += 2;
236	  }
237	
238	  const missing = knownFlags.filter((flag) => {
239	    if (!flag.required) return false;
240	    if (flag.multiple) {
241	      return (multipleFields[flag.name]?.length ?? 0) === 0;
242	    }
243	    return fields[flag.name] === undefined;
244	  });
245	
246	  if (missing.length > 0) {
247	    const names = missing.map((f) => `--${f.name}`).join(", ");
248	    return { message: `missing required flag(s): ${names}` };
249	  }
250	
251	  return {
252	    item: {
253	      kind: verb,
254	      type,
255	      fields,
256	      multipleFields,
257	      raw: line,
258	    },
259	  };
260	}
