1	//! Landscape snapshot — merged read model for `residual view` / `residual serve`.
2	//!
3	//! Two sources feed a snapshot: the sidecar tip metadata (`storage::metadata_dir`)
4	//! and the capture-session working tree (`config_host_dir` after `branch edit`, or
5	//! the inline residual/ dir). Working records win on id collision so an operator
6	//! sees uncommitted capture-session work in the landscape.
7	
8	use anyhow::Result;
9	use serde::{Deserialize, Serialize};
10	use std::path::{Path, PathBuf};
11	
12	use crate::config::Config;
13	use crate::storage::{
14	    attractors, components, defense, purposes, residues, stressors,
15	};
16	
17	/// Which on-disk ledger a record came from.
18	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
19	#[serde(rename_all = "lowercase")]
20	pub enum RecordSource {
21	    /// Sidecar tip metadata (committed).
22	    Sidecar,
23	    /// Capture-session / working metadata (uncommitted).
24	    Working,
25	}
26	
27	/// Stressor vs purpose, for force-list filtering in the UI.
28	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
29	#[serde(rename_all = "lowercase")]
30	pub enum ForceKind {
31	    Stressor,
32	    Purpose,
33	}
34	
35	/// Resolved read sources for a snapshot. `working_dir` is `None` when the
36	/// capture-session dir is absent or identical to the sidecar dir.
37	#[derive(Debug, Clone, PartialEq, Eq)]
38	pub struct LandscapeSources {
39	    pub sidecar_dir: Option<PathBuf>,
40	    pub working_dir: Option<PathBuf>,
41	}
