96	/// Defense ledger projection. Present only when `include_defense` is true.
97	#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
98	pub struct DefenseSection {
99	    pub meta_stressors: Vec<SnapshotMetaForce>,
100	    pub meta_purposes: Vec<SnapshotMetaForce>,
101	    pub meta_attractors: Vec<SnapshotAttractor>,
