108	/// Everything the HTML landscape renders from.
109	#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
110	pub struct LandscapeSnapshot {
111	    pub attractors: Vec<SnapshotAttractor>,
112	    pub stressors: Vec<SnapshotForce>,
113	    pub purposes: Vec<SnapshotForce>,
114	    pub components: Vec<SnapshotComponent>,
115	    pub residues: Vec<SnapshotResidue>,
116	    /// Omitted entirely (no JSON key) unless the snapshot was loaded with `--defense`.
117	    #[serde(default, skip_serializing_if = "Option::is_none")]
118	    pub defense: Option<DefenseSection>,
119	}
