128	/// Resolve sidecar + capture-session dirs from a loaded config.
129	pub fn resolve_sources(cfg: &Config) -> Result<LandscapeSources> {
130	    let sidecar_dir = crate::storage::metadata_dir(cfg)?;
131	    let working = &cfg.config_host_dir;
132	    let working_dir = if working != &sidecar_dir && working.is_dir() {
133	        Some(working.clone())
134	    } else {
135	        None
136	    };
137	    Ok(LandscapeSources {
138	        sidecar_dir: Some(sidecar_dir),
139	        working_dir,
140	    })
141	}
142	
143	/// Load and merge a landscape snapshot from explicit directories (pure, git-free).
144	pub fn load_landscape_snapshot_from_sources(
145	    sources: &LandscapeSources,
146	    include_defense: bool,
147	) -> Result<LandscapeSnapshot> {
148	    let mut snap = LandscapeSnapshot::default();
149	
150	    if let Some(dir) = &sources.sidecar_dir {
151	        merge_main_ledger(&mut snap, dir, RecordSource::Sidecar)?;
152	    }
153	    if let Some(dir) = &sources.working_dir {
154	        merge_main_ledger(&mut snap, dir, RecordSource::Working)?;
155	    }
156	
157	    if include_defense {
158	        let mut defense_section = DefenseSection::default();
159	        if let Some(dir) = &sources.sidecar_dir {
160	            merge_defense(&mut defense_section, dir, RecordSource::Sidecar)?;
161	        }
162	        if let Some(dir) = &sources.working_dir {
163	            merge_defense(&mut defense_section, dir, RecordSource::Working)?;
164	        }
165	        snap.defense = Some(defense_section);
166	    }
167	
168	    Ok(snap)
169	}
170	
171	fn merge_main_ledger(
172	    snap: &mut LandscapeSnapshot,
173	    dir: &Path,
174	    source: RecordSource,
175	) -> Result<()> {
176	    for a in attractors::load(dir)? {
177	        let id = a.id.clone();
178	        upsert(&mut snap.attractors, |x| x.id == id, SnapshotAttractor {
179	            id: a.id,
180	            name: a.name,
181	            description: a.description,
182	            positive_state: a.positive_state,
183	            negative_state: a.negative_state,
184	            source,
185	        });
186	    }
187	
188	    for s in stressors::load(dir)? {
189	        let id = s.id.clone();
190	        upsert(&mut snap.stressors, |x| x.id == id, SnapshotForce {
191	            id: s.id,
192	            shortname: s.shortname,
193	            description: s.description,
194	            naive_change: s.naive_change,
195	            outcomes: s.outcomes,
196	            attractor_id: s.attractor_id,
197	            kind: ForceKind::Stressor,
198	            source,
199	        });
200	    }
201	
202	    for p in purposes::load(dir)? {
203	        let id = p.id.clone();
204	        upsert(&mut snap.purposes, |x| x.id == id, SnapshotForce {
205	            id: p.id,
206	            shortname: p.shortname,
207	            description: p.description,
208	            naive_change: p.naive_change,
209	            outcomes: p.outcomes,
210	            attractor_id: p.attractor_id,
211	            kind: ForceKind::Purpose,
212	            source,
213	        });
214	    }
215	
216	    for c in components::load(dir)? {
217	        let name = c.name.clone();
218	        upsert(&mut snap.components, |x| x.name == name, SnapshotComponent {
219	            name: c.name,
220	            description: c.description,
221	            status: c.status,
222	            architecture_set: c.architecture_set,
223	            source,
224	        });
225	    }
226	
227	    for r in residues::load(dir)? {
228	        let force_id = r.force_id.clone();
229	        let component_id = r.component_id.clone();
230	        let coupled = r.is_coupled();
231	        let whole_system = r.is_whole_system();
232	        upsert(
233	            &mut snap.residues,
234	            |x| x.force_id == force_id && x.component_id == component_id,
235	            SnapshotResidue {
236	                force_id: r.force_id,
237	                component_id: r.component_id,
238	                coupled,
239	                whole_system,
240	                notes: r.notes,
241	                source,
242	            },
243	        );
244	    }
245	
246	    Ok(())
247	}
