346	/// Load the merged snapshot for a loaded config.
347	pub fn load_landscape_snapshot(cfg: &Config, include_defense: bool) -> Result<LandscapeSnapshot> {
348	    let sources = resolve_sources(cfg)?;
349	    load_landscape_snapshot_from_sources(&sources, include_defense)
350	}
