365	    /// Core read model: main ledger CSVs land in the snapshot with filterable fields.
366	    #[test]
367	    fn snapshot_loads_forces_attractors_components_and_residues() {
368	        let dir = tempdir().unwrap();
369	        let ledger = dir.path().join("residual");
370	        seed_main_ledger(&ledger);
371	
372	        let snap = load_landscape_snapshot_from_dir(&ledger, false)
373	            .expect("snapshot must load from a seeded ledger dir");
374	
375	        assert_eq!(snap.attractors.len(), 1, "expected A-01 in snapshot");
376	        assert_eq!(snap.attractors[0].id, "A-01");
377	        assert_eq!(snap.attractors[0].positive_state, "coherent NKP");
378	
379	        assert_eq!(snap.stressors.len(), 1, "expected S-01 in snapshot");
380	        let s = &snap.stressors[0];
381	        assert_eq!(s.id, "S-01");
382	        assert_eq!(s.shortname, "queue-overload");
383	        assert_eq!(s.attractor_id, "A-01");
384	        assert_eq!(s.naive_change, "add retry");
385	        assert_eq!(s.kind, ForceKind::Stressor);
386	
387	        assert_eq!(snap.purposes.len(), 1, "expected P-01 in snapshot");
388	        assert_eq!(snap.purposes[0].id, "P-01");
389	        assert_eq!(snap.purposes[0].kind, ForceKind::Purpose);
390	
391	        let names: Vec<&str> = snap.components.iter().map(|c| c.name.as_str()).collect();
392	        assert!(names.contains(&"auth"), "components: {names:?}");
393	        assert!(names.contains(&"db"), "components: {names:?}");
394	        assert_eq!(
395	            snap.components
396	                .iter()
397	                .find(|c| c.name == "auth")
398	                .map(|c| c.architecture_set.as_str()),
399	            Some("iter1"),
400	            "architecture_set must survive into the snapshot for filtering"
401	        );
402	
403	        assert!(
404	            snap.residues
405	                .iter()
406	                .any(|r| r.force_id == "S-01" && r.component_id == "auth" && r.coupled),
407	            "S-01 × auth coupling must appear as a matrix cell, got {:?}",
408	            snap.residues
409	        );
