export interface SnapshotAttractor { id: string; name: string; description: string; positiveState: string; negativeState: string }
export interface SnapshotComponent { name: string; description: string; status: "proposed" | "actual"; architectureSet: string }
export interface SnapshotForce { id: string; kind: "stressor" | "purpose"; description: string; attractorId: string; naiveChangeOrFeature: string; outcomes: string; shortname: string; components: string[] }
export interface SnapshotPersona { name: string; role: string; concerns?: string; desires?: string }
export interface SnapshotTerm { term: string; definition: string; domain?: string; related?: string }
export type AddedForce = SnapshotForce & { tempId: string };
export type ForceUpdate = Partial<Omit<SnapshotForce, "id" | "kind">>;
export type AttractorUpdate = Partial<Omit<SnapshotAttractor, "id">>;
export type ComponentUpdate = Partial<Omit<SnapshotComponent, "name">>;
export type PersonaUpdate = Partial<Omit<SnapshotPersona, "name">>;
export type TermUpdate = Partial<Omit<SnapshotTerm, "term">>;

export interface PendingState {
  baseAttractors: SnapshotAttractor[]; baseComponents: SnapshotComponent[]; baseForces: SnapshotForce[];
  basePersonas: SnapshotPersona[]; baseTerms: SnapshotTerm[];
  addedAttractors: SnapshotAttractor[]; addedComponents: SnapshotComponent[]; addedForces: AddedForce[];
  addedPersonas: SnapshotPersona[]; addedTerms: SnapshotTerm[];
  updatedAttractors: Record<string, AttractorUpdate>; updatedComponents: Record<string, ComponentUpdate>;
  updatedForces: Record<string, ForceUpdate>; updatedPersonas: Record<string, PersonaUpdate>;
  updatedTerms: Record<string, TermUpdate>;
}

export type RequiredForceField = "description" | "attractorId" | "naiveChangeOrFeature";
export interface OrderedEntry { bucket: "component"|"attractor"|"persona"|"term"|"force"; action: "add"|"update"; key: string }
export interface StateValidity { invalidForceIds: Set<string>; invalidReasonsByForce: Record<string, string[]> }
export interface CommandLine { line: string; valid: boolean }
```

Functions (all stubbed with `throw new Error("not yet implemented — green phase")`): `isForceValid`, `computeStateValidity`, `orderedEntries`, `toCommandLines`.

## Key design decisions (documented in file-header comments)

- `SnapshotAttractor` gained a `description` field beyond the task's sketch — `add attractor --description` is `required: true` in `web/generated/cli-schema.json`, so it's needed to ever emit a valid line.
- Required-fields ground truth is `cli-schema.json`, not the plan prose: `add stressor`/`add purpose` require `description`, `attractor-id`, `naive-change`/`feature` but **not** `outcomes` (schema says `required: false`) — `isForceValid` deliberately excludes outcomes.
- `add stressor`/`add purpose` have no `--add-component` flag in the schema — only `update` does — so a brand-new force's component toggles always surface as a synthetic follow-up `update <type> --force-id <tempId> --add-component ...` entry in the update phase, keyed by the force's `tempId`.
- Terms are tracked as their own bucket, ordered last in both add and update phases (plan's ordering rule only names components/attractors/personas/forces).

## Tests added (19)

`isForceValid` (6): valid-all-set, invalid-empty-description/attractorId/naiveChangeOrFeature, invalid-zero-components, outcomes-not-checked.
`computeStateValidity` (3): base-force-update-blanks-field, added-force-missing-attractorId-keyed-by-tempId, valid-force-not-flagged.
`orderedEntries` (3): full bucket+add/update ordering, added-force-with-components synthetic update entry, terms-ordered-last.
`toCommandLines` (7): valid-line-rendering, invalid-line-flagged, add-stressor round-trip via `parseImportText`, synthetic update-line round-trip, base-force component-diff (add/remove-component), add-attractor round-trip, add-component round-trip.

